import java.util.function.*;

public class Ex08 {
    static class A {
        private final Supplier<B> bSupplier;
        A(Supplier<B> s) { this.bSupplier = s; }
        B getB() { return bSupplier.get(); }
    }
    static class B { final A a; B(A a) { this.a = a; } }
    public static void main(String[] args) {
        final B[] bRef = new B[1];
        A a = new A(() -> bRef[0]);   // 延迟到使用时才取 b
        B b = new B(a);
        bRef[0] = b;                  // 注入 b 的引用
        System.out.println("a.getB() non-null? " + (a.getB() != null));
        System.out.println("b.a == a? " + (b.a == a));
        System.out.println("a.getB().a == a? " + (a.getB().a == a));
    }
}
